message.content:
{
  "summary": "在室外篮球场上，一名穿蓝色背心的男子和一名穿红色背心的女子进行传球练习。两人互相将球抛向对方并接住，最后蓝衣男子将球投向篮筐。",
  "events": [
    {
      "start_s": 0,
      "end_s": 2,
      "description": "红衣女子双手持球，将球抛给前景中的蓝衣男子，男子伸手接住了球。"
    },
    {
      "start_s": 3,
      "end_s": 6,
      "description": "蓝衣男子将球抛回给红衣女子，女子接住后再次将球传给男子。"
    },
    {
      "start_s": 7,
      "end_s": 10,
      "description": "蓝衣男子接住传来的球，稍作调整后再次将球抛给女子。"
    },
    {
      "start_s": 10,
      "end_s": 15,
      "description": "女子将球传回，蓝衣男子接球后转身面向右侧的篮筐，起跳并将球投出。"
    }
  ],
  "interaction_points": [
    {
      "time_s": 1.5,
      "opportunity": "让玩家控制蓝衣男子接住飞来的球",
      "reason": "此时球正从对面飞向该男子的方向，处于接球的瞬间。"
    },
    {
      "time_s": 4.5,
      "opportunity": "让玩家控制蓝衣男子做出传球动作",
      "reason": "男子已经拿到球并举起双臂，正处于准备将球传出的节点。"
    },
    {
      "time_s": 8.5,
      "opportunity": "让玩家控制蓝衣男子接住飞来的球",
      "reason": "另一颗球正在空中飞向该男子，需要玩家操作来接稳它。"
    },
    {
      "time_s": 12.5,
      "opportunity": "让玩家控制蓝衣男子完成投篮出手",
      "reason": "男子已经转向篮筐并高高举起手臂，处于投篮发力的关键时刻。"
    }
  ]
}

